import importlib
import inspect
import time

import Pyro4
from Pyro4.errors import CommunicationError
from Pyro4.util import SerializerBase

from ...exceptions import ServerVersionMismatch
from .pyro_server.exceptions import PyroSerializableError


Pyro4.config.MAX_RETRIES = 5


class PyroProxyHandle(Pyro4.Proxy):
    def __init__(self, uri, version, connected_socket=None):
        super().__init__(uri=uri, connected_socket=connected_socket)
        self._pyroHandshake = version

    def _pyroValidateHandshake(self, response):
        if response != self._pyroHandshake:
            host, port = self._pyroUri.host, self._pyroUri.port
            raise ServerVersionMismatch(
                f"Incompatible Pyro server is already running on {host}:{port}; "
                f"taf.hw.rmod_serial_interface version = {self._pyroHandshake}; "
                f"Server reports version = {response}"
            )

    def is_reachable(self):
        try:
            self._pyroBind()
            return True
        except CommunicationError:
            return False

    def wait_till_reachable(self, timeout):
        start = time.monotonic()
        while time.monotonic() < start + timeout:
            if self.is_reachable():
                return
            time.sleep(0.1)
        raise CommunicationError("Server not reachable")


def register_exception_deserializer():
    for name, cls in inspect.getmembers(
        importlib.import_module(".pyro_server.exceptions", package="taf.hw.rmod_serial_interface.clients.pyro"),
        inspect.isclass,
    ):
        if issubclass(cls, PyroSerializableError):
            SerializerBase.register_dict_to_class(classname=name, converter=cls.to_class)


register_exception_deserializer()
